import{_ as t,a0 as r,w as o,s as d,ao as n,I as h,a1 as e,A as a,x as s}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const w=JSON.parse('{"title":"Linux Shell 介绍：Bash、Zsh 和 Fish | LCTT x X-CMD","titleTemplate":false,"description":"Linux Shell 介绍：Bash、Zsh 和 Fish | LCTT (202307) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux Shell 介绍：Bash、Zsh 和 Fish | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux Shell 介绍：Bash、Zsh 和 Fish | LCTT (202307) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202307/20230719.2 ⭐️⭐️ Linux Shells Bash, Zsh, and Fish Explained","title":"Linux Shell 介绍：Bash、Zsh 和 Fish","tag":"202307","desc":""},"relativePath":"202307/20230719.2 ⭐️⭐️ Linux Shells Bash, Zsh, and Fish Explained.md","filePath":"[post].md"}'),p={name:"202307/20230719.2 ⭐️⭐️ Linux Shells Bash, Zsh, and Fish Explained.md"};function u(x,l,f,b,S,m){const i=r("Link");return o(),d("div",null,[l[28]||(l[28]=n('<h1 id="linux-shell-介绍-bash、zsh-和-fish" tabindex="-1">Linux Shell 介绍：Bash、Zsh 和 Fish <a class="header-anchor" href="#linux-shell-介绍-bash、zsh-和-fish" aria-label="Permalink to “Linux Shell 介绍：Bash、Zsh 和 Fish”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202307/27/152721rd48wwn7xxfkngdw.jpg" alt=""></p><blockquote><p>关于著名的 Linux Shell - Bash、Zsh 和 Fish 的一些注释和特性。</p></blockquote><p>Linux 之所以强大，是因为它提供了用于与系统进行交互的多功能的命令行界面。在这中情况下，Shell 扮演了用户和 Linux 内核之间的桥梁。本文将探讨三种流行的 Linux Shell - Bash、Zsh 和 Fish，并深入了解它们的独特特性和功能。</p><h3 id="理解-linux-shell" tabindex="-1">理解 Linux Shell <a class="header-anchor" href="#理解-linux-shell" aria-label="Permalink to “理解 Linux Shell”">​</a></h3><h4 id="什么是-shell" tabindex="-1">什么是 Shell？ <a class="header-anchor" href="#什么是-shell" aria-label="Permalink to “什么是 Shell？”">​</a></h4><p>Shell 是一个命令行解释器，允许你通过文本命令与操作系统进行交互。它接收你的输入，处理它，并与 Linux 内核通信以执行所请求的操作。最后，它会给你一个输出。</p><p>（LCTT 译注：“Shell” 一词大约取自其“界面”、“外壳”的含义。）</p><p>Shell 在 Linux 中起着至关重要的作用，因为它们使用户能够执行各种任务，从简单的文件导航到复杂的系统管理任务。不同的 Shell 提供各种功能，因此选择适合你工作流程的 Shell 至关重要。</p><h3 id="bash" tabindex="-1">Bash <a class="header-anchor" href="#bash" aria-label="Permalink to “Bash”">​</a></h3>',10)),h("p",null,[e(i,{href:"https://www.gnu.org/software/bash/"},{default:a(()=>[...l[0]||(l[0]=[s("Bash",-1)])]),_:1}),l[1]||(l[1]=s("，全称 “Bourne Again SHell”，是 Linux 发行版中最广泛使用的默认 Shell 之一。它以其简洁和兼容性而闻名，是初学者的优秀选择。",-1))]),l[29]||(l[29]=n('<h4 id="bash-的特点" tabindex="-1">Bash 的特点 <a class="header-anchor" href="#bash-的特点" aria-label="Permalink to “Bash 的特点”">​</a></h4><p>Bash 具有众多特性，包括：</p><ul><li>命令历史：使用箭头键轻松访问先前执行的命令。</li><li><code>Tab</code> 键补全：节省时间，让 Bash 为你自动完成文件名和命令。</li><li>脚本编写：编写和运行 Shell 脚本以自动化重复任务。从这个角度来看，它也是一个程序。</li><li>Bash 在大多数 GNU/Linux 系统中默认安装。</li><li>配置设置存储在家目录下的 <code>.bashrc</code> 文件中。</li></ul><p>和其他 Shell 一样，Bash 有其优点和缺点。使用 Bash 的一些优势包括广泛的使用性、详尽的文档以及庞大的社区支持。然而，Bash 可能缺乏其他 Shell 中存在的一些现代化特性。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/07/Bash-shell-in-Linux.jpg" alt="Linux 中的 Bash shell"></p><h4 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to “安装”">​</a></h4><ul><li>在 Linux 发行版中打开终端。</li><li>输入 <code>bash --version</code> 检查是否已安装 Bash。</li><li>若尚未安装，使用软件包管理器安装 Bash。例如，在 Ubuntu 上，输入 <code>sudo apt-get install bash</code>。</li><li>对于 Fedora 和基于 RPM 的 Linux，请使用 <code>sudo dnf install bash</code>。</li></ul><h3 id="zsh" tabindex="-1">Zsh <a class="header-anchor" href="#zsh" aria-label="Permalink to “Zsh”">​</a></h3>',8)),h("p",null,[e(i,{href:"https://www.zsh.org/"},{default:a(()=>[...l[2]||(l[2]=[s("Zsh",-1)])]),_:1}),l[3]||(l[3]=s("，全称 “Z Shell”，是一种强大且功能丰富的 Shell，深受经验丰富的用户欢迎。它吸取了 Bash 和其他 Shell 的优点，提升了用户体验。",-1))]),l[30]||(l[30]=h("h4",{id:"zsh-的优势",tabindex:"-1"},[s("Zsh 的优势 "),h("a",{class:"header-anchor",href:"#zsh-的优势","aria-label":"Permalink to “Zsh 的优势”"},"​")],-1)),l[31]||(l[31]=h("p",null,"Zsh 提供了几个优势，包括：",-1)),h("ul",null,[l[10]||(l[10]=h("li",null,[s("高级自动补全：Zsh 在 Bash 的基础上提供了更多上下文感知的建议，超越了简单的 "),h("code",null,"Tab"),s(" 键补全。")],-1)),l[11]||(l[11]=h("li",null,[s("当你按下 "),h("code",null,"Tab"),s(" 键时，Zsh 会显示可能的值以供选择，同时进行自动补全。")],-1)),l[12]||(l[12]=h("li",null,"插件支持：通过社区中提供的各种插件，扩展 Zsh 的功能。",-1)),h("li",null,[l[5]||(l[5]=s("这里有一个 ",-1)),e(i,{href:"https://github.com/unixorn/awesome-zsh-plugins"},{default:a(()=>[...l[4]||(l[4]=[s("庞大的 Zsh 主题集合",-1)])]),_:1}),l[6]||(l[6]=s("。",-1))]),h("li",null,[l[8]||(l[8]=s("你还可以使用 ",-1)),e(i,{href:"https://www.debugpoint.com/oh-my-zsh-powerlevel10k/"},{default:a(()=>[...l[7]||(l[7]=[s("Oh My Zsh 脚本",-1)])]),_:1}),l[9]||(l[9]=s(" 进行广泛的自定义。",-1))])]),l[32]||(l[32]=n('<p><img src="https://www.debugpoint.com/wp-content/uploads/2022/12/After-applying-settings-in-powerlevel10k-zsh-theme.jpg" alt="应用 powerlevel10k zsh 主题后的效果"></p><p>Zsh 的复杂性可能使新手感到不知所措，其丰富的配置选项可能会使初学者感到困惑。</p><p>以下是安装 Zsh 的方法：</p><ul><li>在 Linux 发行版中打开终端。</li><li>输入 <code>zsh --version</code> 检查是否已安装 Zsh。</li><li>如果尚未安装，请使用软件包管理器安装 Zsh。</li><li>例如，在 Ubuntu 上，输入 <code>sudo apt-get install zsh</code>。</li><li>对于 Fedora 和基于 RPM 的发行版，输入 <code>sudo dnf install zsh</code>。</li></ul><h3 id="fish-shell" tabindex="-1">Fish Shell <a class="header-anchor" href="#fish-shell" aria-label="Permalink to “Fish Shell”">​</a></h3>',5)),h("p",null,[e(i,{href:"https://fishshell.com/"},{default:a(()=>[...l[13]||(l[13]=[s("Fish",-1)])]),_:1}),l[14]||(l[14]=s("，全称 “Friendly Interactive SHell”，着重于用户友好性和易用性。它拥有现代、直观的界面，特别适合新的 Linux 用户。",-1))]),l[33]||(l[33]=n('<h4 id="fish-的独特特性" tabindex="-1">Fish 的独特特性 <a class="header-anchor" href="#fish-的独特特性" aria-label="Permalink to “Fish 的独特特性”">​</a></h4><p>Fish 的独特之处在于：</p><ul><li>语法高亮：使用彩色标记文本来区分命令、选项和参数。</li><li>自动建议：Fish 根据你的历史记录和当前输入智能地建议命令。</li><li>Fish 被设计为开箱即用的高效工具。但是，你可以通过创建 <code>~/.config/fish/config.fish</code> 文件并添加自定义配置来进一步个性化它。</li></ul><p>虽然 Fish 在用户友好性方面表现出色，但其独特的设计可能并不适合所有人。一些高级用户可能会发现某些功能在高级使用方面有所限制。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/07/Fish-Shell.jpg" alt="Fish Shell"></p><h4 id="fish-shell-的安装" tabindex="-1">Fish Shell 的安装 <a class="header-anchor" href="#fish-shell-的安装" aria-label="Permalink to “Fish Shell 的安装”">​</a></h4><ul><li>在 Linux 发行版中打开终端。</li><li>输入 <code>fish --version</code> 检查是否已安装 Fish。</li><li>如果尚未安装，请使用软件包管理器安装 Fish。例如，在 Ubuntu 上，输入 <code>sudo apt-get install fish</code>。</li><li>对于 Fedora 和其他基于 RPM 的发行版，输入 <code>sudo dnf install fish</code>。</li></ul><h3 id="bash、zsh-和-fish-的比较" tabindex="-1">Bash、Zsh 和 Fish 的比较 <a class="header-anchor" href="#bash、zsh-和-fish-的比较" aria-label="Permalink to “Bash、Zsh 和 Fish 的比较”">​</a></h3><p>为了帮助你决定哪种 Shell 适合你的需求，让我们从各个方面比较这三个流行选择：</p><h4 id="性能与速度" tabindex="-1">性能与速度 <a class="header-anchor" href="#性能与速度" aria-label="Permalink to “性能与速度”">​</a></h4><p>Bash 以其速度和高效性而闻名，适用于资源受限的系统。Zsh 虽然稍慢一些，但其广泛的功能和能力弥补了这一点。作为更具交互性的 Shell，Fish Shell 可能会略微降低性能，但提供了愉快的用户体验。</p><h4 id="用户界面和体验" tabindex="-1">用户界面和体验 <a class="header-anchor" href="#用户界面和体验" aria-label="Permalink to “用户界面和体验”">​</a></h4><p>Bash 的界面简单明了，非常适合初学者，而 Zsh 和 Fish 提供了更引人注目和交互式的界面。Zsh 的高级自动补全和 Fish 的语法高亮为用户创造了视觉上的吸引力。</p><h4 id="可定制性和插件" tabindex="-1">可定制性和插件 <a class="header-anchor" href="#可定制性和插件" aria-label="Permalink to “可定制性和插件”">​</a></h4><p>Zsh 在可定制性方面表现出色，允许用户对其 Shell 环境进行微调。通过庞大的插件集合，Zsh 提供了无与伦比的可扩展性。Fish 则采取了更有主见的方式，专注于开箱即用的可用性，这可能对某些用户有所限制。</p><h3 id="选择合适的-shell" tabindex="-1">选择合适的 Shell <a class="header-anchor" href="#选择合适的-shell" aria-label="Permalink to “选择合适的 Shell”">​</a></h3><p>选择合适的 Shell 与你的具体需求和经验水平密切相关。</p><p>如果你是 Linux 的新手并且更喜欢简单、无花俏的体验，Bash 是一个极好的起点。它的易用性和详尽的文档使其非常适合初学者。</p><p>对于希望更多掌握控制权并愿意花时间进行定制的经验丰富的用户来说，Zsh 强大的功能和插件提供了一个令人兴奋和动态的环境。</p><p>如果你对自动化任务和编写复杂的 Shell 脚本感兴趣，Bash 在 Linux 生态系统中的广泛应用和全面支持使其成为一个可靠的选择。</p><h3 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to “结论”">​</a></h3><p>Bash、Zsh 和 Fish 各有其优势，满足不同用户偏好。如果你刚接触 Linux，Bash 的简单性使其成为一个极好的起点。精通用户和那些寻求定制化的用户可能会觉得 Zsh 更吸引人，而 Fish 的用户友好设计则适合寻求直观界面的初学者。最终，选择权在你手中，探索这些 Shell 将带来更高效和愉悦的 Linux 使用体验。</p><p>你最喜欢的 Shell 是什么？在下方的评论框中告诉我。</p><p><em>（题图：MJ/b6490b57-63bd-4fdd-bd3f-bf6d4aef1c4a）</em></p><hr>',25)),h("p",null,[l[16]||(l[16]=s("via: ",-1)),e(i,{href:"https://www.debugpoint.com/linux-shells/"},{default:a(()=>[...l[15]||(l[15]=[s("https://www.debugpoint.com/linux-shells/",-1)])]),_:1})]),h("p",null,[l[20]||(l[20]=s("作者：",-1)),e(i,{href:"https://www.debugpoint.com/author/admin1/"},{default:a(()=>[...l[17]||(l[17]=[s("Arindam",-1)])]),_:1}),l[21]||(l[21]=s(" 选题：",-1)),e(i,{href:"https://github.com/lkxed/"},{default:a(()=>[...l[18]||(l[18]=[s("lkxed",-1)])]),_:1}),l[22]||(l[22]=s(" 译者：ChatGPT 校对：",-1)),e(i,{href:"https://github.com/wxy"},{default:a(()=>[...l[19]||(l[19]=[s("wxy",-1)])]),_:1})]),h("p",null,[l[25]||(l[25]=s("本文由 ",-1)),e(i,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...l[23]||(l[23]=[s("LCTT",-1)])]),_:1}),l[26]||(l[26]=s(" 原创编译，",-1)),e(i,{href:"https://linux.cn/"},{default:a(()=>[...l[24]||(l[24]=[s("Linux中国",-1)])]),_:1}),l[27]||(l[27]=s(" 荣誉推出",-1))])])}const B=t(p,[["render",u]]);export{w as __pageData,B as default};
